package com.salespunch360.mobile
import android.app.Application;import androidx.lifecycle.AndroidViewModel;import androidx.lifecycle.viewModelScope;import com.salespunch360.mobile.data.*;import java.io.IOException;import kotlinx.coroutines.flow.*;import kotlinx.coroutines.launch;import kotlinx.serialization.json.*
data class AccountReportState(val loading:Boolean=false,val report:String?=null,val from:String=java.time.LocalDate.now().withDayOfYear(1).toString(),val to:String=java.time.LocalDate.now().toString(),val branchId:String="",val projectId:String="",val ledgerId:String="",val customerId:String="",val vendorId:String="",val productId:String="",val options:JsonObject=buildJsonObject{},val data:JsonObject?=null,val export:Pair<String,ByteArray>?=null,val error:String?=null)
class AccountReportViewModel(app:Application):AndroidViewModel(app){private val api=ApiClient(SecureSession(app));private val _state=MutableStateFlow(AccountReportState());val state:StateFlow<AccountReportState> = _state;init{options()};private fun options()=viewModelScope.launch{try{_state.value=_state.value.copy(options=api.accountReportOptions())}catch(e:Exception){fail(e)}};fun choose(r:String?){_state.value=_state.value.copy(report=r,data=null);if(r!=null)run()};fun dates(f:String,t:String){_state.value=_state.value.copy(from=f,to=t)};fun filter(key:String,v:String){_state.value=when(key){"branch"->_state.value.copy(branchId=v);"project"->_state.value.copy(projectId=v);"ledger"->_state.value.copy(ledgerId=v);"customer"->_state.value.copy(customerId=v);"vendor"->_state.value.copy(vendorId=v);else->_state.value.copy(productId=v)}};private fun filters()=buildMap{put("from",_state.value.from);put("to",_state.value.to);listOf("branchId" to _state.value.branchId,"projectId" to _state.value.projectId,"ledgerId" to _state.value.ledgerId,"customerId" to _state.value.customerId,"vendorId" to _state.value.vendorId,"productId" to _state.value.productId).forEach{(k,v)->if(v.isNotBlank())put(k,v)}};fun run()=viewModelScope.launch{val r=_state.value.report?:return@launch;try{_state.value=_state.value.copy(loading=true,error=null,data=api.accountReport(r,filters()),loading=false)}catch(e:Exception){fail(e)}};fun export(format:String)=viewModelScope.launch{val r=_state.value.report?:return@launch;try{_state.value=_state.value.copy(export="$r.$format" to api.accountReportExport(r,format,filters()))}catch(e:Exception){fail(e)}};fun consumed(){_state.value=_state.value.copy(export=null)};private fun fail(e:Exception){_state.value=_state.value.copy(loading=false,error=if(e is IOException)"Offline. Report was not refreshed." else "Report request rejected by server.")}}
